#include <iostream>
#include <vector>
#include <iomanip>
#include <cmath>
#include <algorithm>

using namespace std;

/**
 * Problem: 10533 - The Trip
 * 
 * 解題思路：
 * 1. 為了避免浮點數誤差，將所有金額轉換為「美分」(cents)。
 * 2. 計算總金額 total_cents 和平均金額 avg_cents = total_cents / n。
 * 3. 餘數 remainder = total_cents % n 代表有多少人需要多付 1 美分。
 * 4. 理想情況下，n - remainder 個人支付 avg_cents，remainder 個人支付 avg_cents + 1。
 * 5. 最小交換金額為：所有「付得比他該付的多」的人多付的總額，
 *    或是所有「付得比他該付的少」的人少付的總額（兩者取大值或相等）。
 */

int main() {
    int n;
    while (cin >> n && n != 0) {
        vector<long long> expenses(n);
        long long total_cents = 0;
        for (int i = 0; i < n; ++i) {
            double val;
            cin >> val;
            // 四捨五入到最近的整數美分
            expenses[i] = (long long)(val * 100.0 + 0.5);
            total_cents += expenses[i];
        }

        long long avg_cents = total_cents / n;
        long long remainder = total_cents % n;

        long long positive_diff = 0;
        long long negative_diff = 0;

        // 為了讓每個人差距不超過 1 美分，我們將支出排序
        sort(expenses.begin(), expenses.end());

        for (int i = 0; i < n; ++i) {
            // 前 n - remainder 個人支付 avg_cents
            // 後 remainder 個人支付 avg_cents + 1
            long long target = (i < n - remainder) ? avg_cents : avg_cents + 1;
            if (expenses[i] > target) {
                positive_diff += expenses[i] - target;
            } else {
                negative_diff += target - expenses[i];
            }
        }

        // 最小交換額即為正向或負向差額的較大者（在此邏輯下應相等）
        long long result_cents = max(positive_diff, negative_diff);

        cout << "$" << result_cents / 100 << "." << setfill('0') << setw(2) << result_cents % 100 << endl;
    }
    return 0;
}
